precision mediump float;
varying vec2 v_uv;
uniform sampler2D u_tex;
uniform vec2 u_res;
uniform float u_amount;
// Brillo (glow) del original: la imagen desenfocada, mas saturada y brillante, se suma en modo pantalla.
void main() {
  vec4 base = texture2D(u_tex, v_uv);
  vec2 px = 1.0 / u_res;
  vec3 a = vec3(0.0), b = vec3(0.0);
  for (int i = 0; i < 12; i++) {
    float an = float(i) * 0.5235988;
    vec2 d = vec2(cos(an), sin(an));
    a += texture2D(u_tex, v_uv + d * px * 4.0).rgb;
    b += texture2D(u_tex, v_uv + d * px * 10.0).rgb;
  }
  a /= 12.0; b /= 12.0;
  float la = dot(a, vec3(0.299, 0.587, 0.114)), lb = dot(b, vec3(0.299, 0.587, 0.114));
  vec3 g1 = clamp(mix(vec3(la), a, 3.0) * 1.5, 0.0, 1.0) * 0.55;
  vec3 g2 = clamp(mix(vec3(lb), b, 2.0) * 1.2, 0.0, 1.0) * 0.25;
  vec3 g = (g1 + g2) * u_amount * 0.6;
  gl_FragColor = vec4(1.0 - (1.0 - base.rgb) * (1.0 - g), base.a);
}

precision mediump float;
varying vec2 v_uv;
uniform sampler2D u_tex;
uniform vec2 u_res;
uniform float u_amount;
// Tele vieja: curvatura, lineas de barrido, separacion de color y bordes oscuros. u_amount = intensidad (0 = nada).
void main() {
  vec2 cc = v_uv - 0.5;
  cc *= 1.0 + dot(cc, cc) * 0.3 * u_amount;
  cc += 0.5;
  if (cc.x < 0.0 || cc.x > 1.0 || cc.y < 0.0 || cc.y > 1.0) { gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0); return; }
  vec4 col = texture2D(u_tex, cc);
  col.r = texture2D(u_tex, cc + vec2(0.0015 * u_amount, 0.0)).r;
  col.b = texture2D(u_tex, cc - vec2(0.0015 * u_amount, 0.0)).b;
  float line = sin(cc.y * u_res.y * 3.14159) * 0.5 + 0.5;
  col.rgb *= mix(1.0, mix(0.65, 1.0, line), u_amount);
  if (mod(gl_FragCoord.y, 3.0) < 1.0) col.rgb *= 1.0 - 0.18 * u_amount;
  vec2 v = cc - 0.5;
  col.rgb *= mix(1.0, clamp(1.0 - dot(v, v) * 1.6, 0.0, 1.0), u_amount);
  col.rgb *= 1.0 + 0.06 * u_amount;
  gl_FragColor = col;
}

precision mediump float;
varying vec2 v_uv;
uniform sampler2D u_tex;
uniform float u_time;
uniform vec2 u_res;
uniform float u_amount;
// Ruido de tele (cambio de canal), de un pixel: grano que cambia 30 veces por segundo, bandas que bajan y lineas que tiemblan.
float h(vec2 p) { p = fract(p * vec2(443.897, 441.423)); p += dot(p, p.yx + 19.19); return fract((p.x + p.y) * p.x); }
void main() {
  if (u_amount <= 0.001) { gl_FragColor = texture2D(u_tex, v_uv); return; }
  float t = floor(u_time * 30.0);
  vec2 px = floor(v_uv * u_res);
  float j = (h(vec2(px.y, t)) - 0.5) * 0.03 * u_amount;
  vec4 c = texture2D(u_tex, v_uv + vec2(j, 0.0));
  float n = h(px + vec2(t * 13.0, t * 7.0));
  float banda = 1.0 - 0.35 * smoothstep(0.8, 1.0, sin(v_uv.y * 4.0 - u_time * 5.0) * 0.5 + 0.5);
  float raya = step(0.985, h(vec2(floor(v_uv.y * u_res.y / 2.0), t))) * 0.4;
  vec3 ruido = vec3(n * banda + raya);
  gl_FragColor = vec4(mix(c.rgb, ruido, u_amount), 1.0);
}

precision mediump float;
varying vec2 v_uv;
uniform sampler2D u_tex;
uniform float u_time;
uniform vec2 u_res;
// Fondo de los menus: el color de la capa (FondoRGB) se mueve como plasma, con bandas de luz que cruzan,
// una rejilla en perspectiva que avanza por abajo, el resplandor del horizonte y estrellas que parpadean.
float h(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
void main() {
  vec4 t = texture2D(u_tex, v_uv);
  if (t.a < 0.01) { gl_FragColor = t; return; }
  vec3 base = t.rgb;
  vec2 uv = v_uv;
  float tm = u_time;
  float p = sin(uv.x * 6.0 + tm * 0.7) + sin(uv.y * 5.0 - tm * 0.5) + sin((uv.x + uv.y) * 4.0 + tm * 0.9) + sin(length(uv - 0.5) * 10.0 - tm * 1.3);
  vec3 col = base * (0.55 + 0.12 * p) * (1.15 - 0.5 * uv.y);
  float banda = smoothstep(0.93, 1.0, sin((uv.x * 1.6 + uv.y) * 10.0 - tm * 1.4) * 0.5 + 0.5);
  col += (base + 0.15) * banda * 0.22;
  float hz = 0.66;
  col += (base * 0.6 + vec3(0.35, 0.1, 0.3)) * exp(-abs(uv.y - hz) * 30.0) * 0.55;
  if (uv.y > hz) {
    float d = (uv.y - hz) / (1.0 - hz);
    float z = 1.0 / max(d, 0.03);
    float fx = fract((uv.x - 0.5) * z * 1.8);
    float fy = fract(z * 0.5 - tm * 0.7);
    float lx = 1.0 - smoothstep(0.0, 0.05 * z * 0.25 + 0.02, min(fx, 1.0 - fx));
    float ly = 1.0 - smoothstep(0.0, 0.08, min(fy, 1.0 - fy));
    col += mix(base, vec3(1.0, 0.45, 0.95), 0.55) * max(lx, ly) * d * 0.8;
  } else {
    vec2 c = floor(uv * u_res / 3.0);
    float e = h(c);
    if (e > 0.992) col += vec3(0.7) * (0.5 + 0.5 * sin(tm * 3.0 + e * 60.0)) * (1.0 - uv.y / hz);
  }
  gl_FragColor = vec4(col, 1.0);
}

precision mediump float;
varying vec2 v_uv;
uniform sampler2D u_tex;
// Vineta: oscurece los bordes.
void main() {
  vec4 col = texture2D(u_tex, v_uv);
  vec2 uv = v_uv - 0.5;
  col.rgb *= clamp(1.0 - dot(uv, uv) * 3.5, 0.0, 1.0);
  gl_FragColor = col;
}

#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
varying vec2 v_uv;
uniform sampler2D u_tex;
uniform float u_time;

const vec2 RES = vec2(1280.0, 720.0);
const float INTENSITY = 0.58;
const float OPACITY = 1.0;
const float SPEED = 3.2;
const float WIND = 0.22;
const vec3 TINT = vec3(0.3, 0.58, 1.0);

mat2 rot(float a) { float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
float hash21(vec2 p) { p = fract(p * vec2(233.34, 851.73)); p += dot(p, p + 23.45); return fract(p.x * p.y); }
float rainLayer(vec2 sp, float t, float cols, float rows, float lenH, float widPx, float seed, float pxH, out float head) {
  float drift = t * 0.12 * (0.5 + fract(seed * 0.371));
  vec2 p = vec2(sp.x * cols + drift, sp.y * rows);
  float col = floor(p.x);
  float h = hash21(vec2(col, seed));
  float h2 = hash21(vec2(col, seed + 7.31));
  float h3 = hash21(vec2(col, seed + 13.77));
  float h4 = hash21(vec2(col, seed + 29.13));
  float sway = sin(t * (0.22 + 0.58 * h2) + h3 * 6.2831) * 0.16;
  float x = fract(p.x + sway) - 0.5;
  float speed = 0.72 + 0.95 * h;
  float phaseJit = sin(t * (0.11 + 0.34 * h3) + h2 * 6.2831) * (0.055 + 0.11 * h);
  float travel = fract(t * speed + h * 41.7 + phaseJit);
  float d = fract(travel - p.y);
  float lenPulse = 0.62 + 0.75 * (0.5 + 0.5 * sin(t * (0.17 + 0.29 * h4) + h * 6.2831));
  float wid = max(widPx * pxH * cols * (0.75 + 0.6 * h4), 0.0001);
  float len = clamp(lenH * rows * lenPulse, 0.0001, 0.98);
  float core = 1.0 - smoothstep(0.0, wid, abs(x));
  float tail = 1.0 - smoothstep(0.0, min(len * (0.55 + h * 0.9), 0.98), d);
  float glow = exp(-d * 6.0 / len) * 0.55;
  head = core * (1.0 - smoothstep(0.0, wid * 3.0, d)) * step(0.25, h);
  return core * (tail + glow) * (0.3 + 0.85 * h);
}
void main() {
  vec2 uv = v_uv;
  float aspect = RES.x / RES.y;
  float pxH = 1.0 / RES.y;
  float t0 = u_time;
  float gust = sin(t0 * 0.23) * 0.5 + sin(t0 * 0.61) * 0.5 + sin(t0 * 1.13) * 0.25;
  float wind = WIND + gust * 0.1;
  vec2 sp = rot(wind) * vec2(uv.x * aspect, uv.y);
  float t = t0 * SPEED;
  float h1; float h2; float h3; float h4;
  float r1 = rainLayer(sp, t * 2.25, 52.0, 11.0, 0.08, 1.15, 3.1, pxH, h1);
  float r2 = rainLayer(sp, t * 1.7, 35.0, 7.5, 0.115, 1.8, 17.7, pxH, h2);
  float r3 = rainLayer(sp, t * 1.28, 22.0, 4.6, 0.17, 2.7, 51.3, pxH, h3);
  float r4 = rainLayer(sp, t * 0.8, 10.0, 2.4, 0.25, 7.5, 87.9, pxH, h4) * 0.22;
  float heads = (h1 * 0.5 + h2 * 0.8 + h3 * 1.0) * 0.7;
  float rain = clamp((r1 * 0.3 + r2 * 0.55 + r3 * 0.82 + r4) * INTENSITY, 0.0, 1.5);
  vec2 warp = vec2(r2 - r1, r3 * 0.5) * 0.0055 * INTENSITY;
  vec4 baseG = texture2D(u_tex, uv + warp);
  vec4 baseB = texture2D(u_tex, uv + warp + vec2(0.0018 * rain, 0.0));
  vec4 baseR = texture2D(u_tex, uv + warp - vec2(0.0018 * rain, 0.0));
  vec3 col = vec3(baseR.r, baseG.g, baseB.b);
  float mist = smoothstep(0.35, 1.0, uv.y) * 0.09;
  vec3 rainCol = mix(TINT * 1.2, vec3(0.8, 0.92, 1.18), 0.5);
  col = mix(col, col * vec3(0.48, 0.7, 1.3), clamp(rain * 0.42, 0.0, 1.0));
  col += rainCol * (rain * 0.26);
  col += vec3(0.75, 0.88, 1.2) * heads * 0.22;
  col = mix(col, TINT * 0.5, mist);
  vec2 vq = uv - 0.5;
  col *= 1.0 - dot(vq, vq) * 0.55;
  float g = hash21(uv * RES + fract(t0) * 137.0);
  col += (g - 0.5) * 0.035;
  float alpha = clamp(max(baseG.a, rain * 0.5 * OPACITY), 0.0, 1.0);
  gl_FragColor = vec4(col, alpha);
}
